#include <bits/stdc++.h>
using namespace std;

class DStress2_Variant2 {
public:
    int INF = INT_MAX / 3;

    int calculate(const vector<char>& s) {
        vector<int> vIndices, kIndices, otherIndices;
        for (int i = 0; i < (int)s.size(); i++) {
            switch (s[i]) {
                case 'V': vIndices.push_back(i); break;
                case 'K': kIndices.push_back(i); break;
                default: otherIndices.push_back(i); break;
            }
        }
        int vSize = vIndices.size();
        int kSize = kIndices.size();
        int oSize = otherIndices.size();

        vector<vector<vector<vector<int>>>> dp(2,
            vector<vector<vector<int>>>(vSize + 1,
                vector<vector<int>>(kSize + 1,
                    vector<int>(oSize + 1, INF)
                )
            )
        );

        dp[0][0][0][0] = 0;

        for (int vCount = 0; vCount <= vSize; vCount++) {
            for (int kCount = 0; kCount <= kSize; kCount++) {
                for (int oCount = 0; oCount <= oSize; oCount++) {
                    for (int lastFlag = 0; lastFlag < 2; lastFlag++) {
                        int currentCost = dp[lastFlag][vCount][kCount][oCount];
                        if (currentCost == INF) continue;

                        if (vCount < vSize) {
                            int cost = currentCost + count(vIndices[vCount], kCount, kIndices) + count(vIndices[vCount], oCount, otherIndices);
                            dp[1][vCount + 1][kCount][oCount] = min(dp[1][vCount + 1][kCount][oCount], cost);
                        }
                        if (kCount < kSize && lastFlag == 0) {
                            int cost = currentCost + count(kIndices[kCount], vCount, vIndices) + count(kIndices[kCount], oCount, otherIndices);
                            dp[0][vCount][kCount + 1][oCount] = min(dp[0][vCount][kCount + 1][oCount], cost);
                        }
                        if (oCount < oSize) {
                            int cost = currentCost + count(otherIndices[oCount], vCount, vIndices) + count(otherIndices[oCount], kCount, kIndices);
                            dp[0][vCount][kCount][oCount + 1] = min(dp[0][vCount][kCount][oCount + 1], cost);
                        }
                    }
                }
            }
        }

        return min(dp[0][vSize][kSize][oSize], dp[1][vSize][kSize][oSize]);
    }

private:
    int count(int position, int startIndex, const vector<int>& list) {
        int cnt = 0;
        for (int i = startIndex; i < (int)list.size(); i++) {
            if (list[i] < position) cnt++;
        }
        return cnt;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    cin >> n >> s;
    DStress2_Variant2 solver;
    vector<char> sVec(s.begin(), s.end());
    cout << solver.calculate(sVec) << "\n";
    return 0;
}

